// Extract binary file and encode to base64 for MCP Parser
const item = $input.first();
const binaryData = item.binary ? item.binary.data : null;
const filename = item.json.name || 'document.pdf';

if (!binaryData) {
  throw new Error('File binary tidak ditemukan dari Google Drive');
}

let fileType = 'pdf';
if (filename.endsWith('.docx')) fileType = 'docx';
else if (filename.endsWith('.xlsx')) fileType = 'xlsx';
else if (filename.endsWith('.csv')) fileType = 'csv';
else if (filename.endsWith('.txt')) fileType = 'text';

return [{
  json: {
    filename: filename,
    file_type: fileType,
    file_base64: binaryData.data,
    gdrive_file_id: item.json.id,
    gdrive_mime_type: item.json.mimeType,
    uploaded_at: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════════════════
// SEMANTIC CHUNKER FOR GOOGLE DRIVE INGESTION
// ═══════════════════════════════════════════════════
const parsed = $input.first().json.data || $input.first().json;
const text = parsed.extracted_text || '';
const filename = $('🔄 Binary to Base64 Formatter').item.json.filename;
const metrics = parsed.extracted_metrics || {};

const CHUNK_SIZE = 800;
const CHUNK_OVERLAP = 100;
const chunks = [];

if (text.length > 0) {
  let start = 0;
  let chunkIdx = 0;
  while (start < text.length) {
    const end = Math.min(start + CHUNK_SIZE, text.length);
    const chunkText = text.substring(start, end).trim();
    if (chunkText.length > 50) {
      chunks.push({
        chunk_index: chunkIdx,
        chunk_text: chunkText,
        filename: filename,
        total_characters: chunkText.length
      });
      chunkIdx++;
    }
    start += (CHUNK_SIZE - CHUNK_OVERLAP);
  }
}

return [{
  json: {
    document_title: filename,
    source: 'google_drive',
    total_chunks: chunks.length,
    total_characters: text.length,
    ai_summary: parsed.ai_summary || '',
    extracted_metrics: metrics,
    timestamp: new Date().toISOString()
  }
}];
